static long Summe(long n)
{
    if (n == 0) return 0;
    return n + Summe(n - 1);
}

Console.WriteLine(Summe(1000));
// Ausgabe: 500500
Console.WriteLine(Summe(10_000_000));
// Absturz: Stack overflow.

try
{
    Summe(10_000_000);
}
catch (StackOverflowException)
{
    // wird NIE erreicht!
    Console.WriteLine("Abgefangen");
}

// nicht endrekursiv: nach dem
// Aufruf wird noch multipliziert
static long Fak(int n)
{
    if (n <= 1) return 1;
    return n * Fak(n - 1);
}

// endrekursiv: der Aufruf ist
// das Letzte, was passiert
static long FakE(int n, long akku = 1)
{
    if (n <= 1) return akku;
    return FakE(n - 1, n * akku);
}

Console.WriteLine(Fak(5) + " " + FakE(5));
// Ausgabe: 120 120

static long FakI(int n)
{
    long akku = 1;
    // solange kein Basisfall
    while (n > 1)
    {
        // FakE(n - 1, n * akku)
        akku = n * akku;
        n = n - 1;
    }
    return akku; // Basisfall
}

Console.WriteLine(FakI(20));
// Ausgabe: 2432902008176640000

