static int Ggt(int a, int b)
{
    if (b == 0) return a;
    return Ggt(b, a % b);
}

Console.WriteLine(Ggt(84, 36));

static long F(int n)
{
    long akku = 1;
    while (n > 1)
    {
        n = n - 1;
        akku = n * akku;
    }
    return akku;
}

Console.WriteLine(F(4));
